public class Solution {
    // Conta, acumula as posições finais e distribui de trás para frente (estável). O(n + k).
    static int[][] countingSort(int[][] regs) {
        if (regs.length == 0) return new int[0][];
        int min = Integer.MAX_VALUE, max = Integer.MIN_VALUE;
        for (int[] r : regs) {
            min = Math.min(min, r[0]);
            max = Math.max(max, r[0]);
        }
        int[] cont = new int[max - min + 1];
        for (int[] r : regs) cont[r[0] - min]++;
        for (int i = 1; i < cont.length; i++) cont[i] += cont[i - 1];
        int[][] out = new int[regs.length][];
        for (int i = regs.length - 1; i >= 0; i--) out[--cont[regs[i][0] - min]] = regs[i];
        return out;
    }
}

