import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void estavelComNegativos() {
        int[][] in = {{3, 0}, {-2, 1}, {3, 2}, {0, 3}, {-2, 4}};
        int[][] out = Solution.countingSort(in);
        assertArrayEquals(new int[][]{{-2, 1}, {-2, 4}, {0, 3}, {3, 0}, {3, 2}}, out);
        assertArrayEquals(new int[]{3, 0}, in[0], "a entrada não pode mudar");
    }

    @Test void vazio() {
        assertEquals(0, Solution.countingSort(new int[0][]).length);
    }

    @Test void grande() {
        var rnd = new Random(4);
        int[][] in = new int[1_000_000][];
        for (int i = 0; i < in.length; i++) in[i] = new int[]{rnd.nextInt(1000) - 500, i};
        int[][] out = Solution.countingSort(in);
        for (int i = 1; i < out.length; i++) {
            assertTrue(out[i - 1][0] < out[i][0] || (out[i - 1][0] == out[i][0] && out[i - 1][1] < out[i][1]));
        }
    }
}
